import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import frequenciesApi from "../../../api/drugs/frequenciesApi";
import { Modal } from "antd";
import routesApi from "../../../api/drugs/routesApi";
import retailersApi from "../../../api/retailers/retailersApi";


export default function RetailPrescriptionItemModal({
  openPrescriptionModal,
  setopenPrescriptionModal,
  selectedProduct,
  setPrescription,
  prescription,
  prescriptionItem=null,
  setprescriptionItem,
  selectedRowKeys,
  setSelectedRowKeys,
  updateData,setupdateData

}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, dangerColor, loggedInUser } = useStateContext();

  //Retrieve frequencies
  const [frequencies, setFrequencies] = useState([]);
  const getFrequenciesApi = useApi(frequenciesApi.frequenciesAction);
  const getFrequencies = async () => {
    await getFrequenciesApi.request({
      action: "GetFrequencies",
    });
  };


  const [routes, setroutes] = useState([]);
  const getRoutesApi = useApi(routesApi.routesAction);
  const getRoutes = async () => {
    await getRoutesApi.request({
      action: "GetRoutes",
    });
  };

  useEffect(() => {
    if (getRoutesApi.data && getRoutesApi.data.length) {
      setroutes(
        getRoutesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
  }, [getRoutesApi.data]);

  useEffect(() => {
    if (user != null) {
      getFrequencies();
      getRoutes();
    }
  }, [user]);

  useEffect(() => {
    if (getFrequenciesApi.data && getFrequenciesApi.data.length) {
      setFrequencies(
        getFrequenciesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
    console.log("getFrequenciesApi.data", getFrequenciesApi.data);
  }, [getFrequenciesApi.data]);

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);















  const formik = useFormik({
    initialValues: {
      frequency: "",
      days: "",
      dose: "",
      route: "",

    },

    validationSchema: Yup.object({
      frequency: Yup.object().required("Frequency is required"),
      route: Yup.object().required("Route is required"),
      days: Yup.number().required("Duration is required"),
      dose: Yup.string().required("Dosage is required"),

    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      const data = {

        "action": "CreateRetailPrescriptionItem",
        "prescription": prescription.id,
        "preparation": selectedProduct.preparation ? selectedProduct.preparation : "",
        "product": selectedProduct.id,
        "route": values.route.value,
        "frequency": values.frequency.value,
        "dose": values.dose,
        "days": values.days

      }
      console.log("data", data);

      setprescriptionItem(data)
      setopenPrescriptionModal(false)
      setSelectedRowKeys([])
      // handleCreatePrescriptionItem(data);



      // resetForm();
    },
  });



  const handleOk = () => {
    setopenPrescriptionModal(false);
  };
  const handleCancel = () => {
    setopenPrescriptionModal(false);
  };

  return (
    <div className=" max-w-fit min-w-fit">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedProduct ? selectedProduct.long_title : ""}
        open={openPrescriptionModal}
        onOk={handleOk}
        onCancel={handleCancel}
        maskClosable={false}
        closeIcon={true}
        closable={true}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            className="w-full"
            touched={formik.touched.route}
            error={formik.errors.route}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="route"
              id="route"

              size="large"
              onChange={(value) => formik.setFieldValue("route", value)}
              value={formik.values.route}
              placeholder="Select route"

              options={routes}
            />
          </CustomFormItem>
          <CustomFormItem
            className="w-full"
            touched={formik.touched.frequency}
            error={formik.errors.frequency}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="frequency"
              id="frequency"

              size="large"
              onChange={(value) => formik.setFieldValue("frequency", value)}
              value={formik.values.frequency}
              placeholder="Select drug administration frequency"

              options={frequencies}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.dose}
            error={formik.errors.dose}
            className="w-full"
          >
            <CustomInput
              id="dose"
              name="dose"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter dose"
              label="Enter dose"
              size="large"
              type="text"
              value={formik.values.dose}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.days}
            error={formik.errors.days}
            className="w-full"
          >
            <CustomInput
              id="days"
              name="days"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter duration in days"
              label="Enter duration in days"
              size="large"
              type="number"
              value={formik.values.days}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.instruction}
            error={formik.errors.instruction}
            className="w-full"
          >
            <CustomTextArea

              rows={2}
              id="instruction"
              name="instruction"
              onChange={formik.handleChange}
              placeholder="Any special instruction?"
              label="Any special instruction?"
              size="large"
              type="text"
              value={formik.values.instruction}
            />
          </CustomFormItem>

          <div className="w-full items-center flex-row mt-2">
            <Button
              style={{ background: dangerColor }}
              className="w-36 rounded-md mx-1"
              color="primary"
              type="button"
              onPress={() => handleCancel()}
            >
              Cancel
            </Button>
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md mx-1"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
